const c = $input.first().json;
const tag = String(c.STATUS_TAG || 'account').replace(/[^a-zA-Z0-9._-]/g, '');
const status = `/tmp/oriphiel-imap-backfill-${tag}.json`;
const command = [
  'cd /root/oriphiel-ai/oriphiel_messaging',
  `if pgrep -f sync-imap-backfill.py >/dev/null; then echo ALREADY_RUNNING; cat ${status} 2>/dev/null; exit 0; fi`,
  `nohup env ENV_FILE=${c.ENV_FILE} ACCOUNT_EMAIL=${c.ACCOUNT_EMAIL} RESET_BEFORE=${c.RESET_BEFORE} RUN_AI=${c.RUN_AI} BATCH_SIZE=${c.BATCH_SIZE} MARK_AS_SEEN=${c.MARK_AS_SEEN} STATUS_FILE=${status} bash sync-imap-backfill.sh >>/tmp/oriphiel-imap-backfill-last.log 2>&1 &`,
  `echo STARTED_PID=$! account=${c.ACCOUNT_EMAIL} RUN_AI=${c.RUN_AI}`,
  'sleep 2',
  `cat ${status} 2>/dev/null || echo status_pending`
].join(' && ');
return [{ json: { ...c, command, status_file: status } }];

const c = $input.first().json;
const tag = String(c.STATUS_TAG || 'account').replace(/[^a-zA-Z0-9._-]/g, '');
const status = `/tmp/oriphiel-ai-enrich-${tag}.json`;
const email = String(c.ACCOUNT_EMAIL).replace(/'/g, "'\\''");
const command = [
  'cd /root/oriphiel-ai/oriphiel_messaging',
  `if pgrep -f enrich-existing-messages.py >/dev/null; then echo ALREADY_RUNNING; cat ${status} 2>/dev/null; exit 0; fi`,
  `if [ ! -f ollama-enrich-message.py ] || [ ! -f enrich-existing-messages.py ]; then echo MISSING_FILES; exit 2; fi`,
  `nohup env ACCOUNT_EMAIL='${email}' ONLY_MISSING=1 LIMIT=0 BATCH_SIZE=10 OLLAMA_MODEL=llama3.1:8b STATUS_FILE=${status} python3 -u enrich-existing-messages.py >>/tmp/oriphiel-ai-enrich-last.log 2>&1 &`,
  `echo STARTED_PID=$! account=${email}`,
  'sleep 2',
  `cat ${status} 2>/dev/null || echo status_pending`
].join(' && ');
return [{ json: { ...c, command, status_file: status } }];
